WITH stages AS (SELECT user_id, MIN(CASE WHEN event_name='view' THEN event_time END) AS viewed, MIN(CASE WHEN event_name='checkout' THEN event_time END) AS checkout, MIN(CASE WHEN event_name='pay' THEN event_time END) AS paid FROM events GROUP BY user_id) SELECT COUNT(*) AS viewed_users, SUM(CASE WHEN checkout>viewed THEN 1 ELSE 0 END) AS checkout_users, SUM(CASE WHEN paid>checkout AND checkout>viewed THEN 1 ELSE 0 END) AS paid_users FROM stages WHERE viewed IS NOT NULL;
